package purchase

import (
	"fmt"
	"strings"
	"time"

	"github.com/witsaba/paca/packages/domain/account"
	"github.com/witsaba/paca/packages/domain/business"
	"github.com/witsaba/paca/packages/domain/ledger"
)

// ID is the identity of a purchase.
//
// The number is generated by the database: it is the counter of the
// purchases and not a number of the person. The type exists so that an
// identifier never travels as a plain integer by accident.
type ID int64

// Purchase is the fact of what the business bought.
//
// A purchase never changes: it is what was bought, on the day it was
// bought, at the market it was bought in, with the invoice it came with,
// with the lines it carries, with the sentence the owner said and with the
// word she used to confirm it.
//
// The money of a purchase is whole pesos: the book counts the pesos the
// person has, and a price in centavos is rounded to the nearest peso when
// it enters the book.
type Purchase struct {
	// ID is the identity of the purchase. It is empty until the storage
	// writes the row.
	ID ID

	// DraftID is the draft the purchase came from. It is the draft the
	// owner saw, and the one the purchase answers.
	DraftID DraftID

	// BusinessID is the business that bought.
	BusinessID business.ID

	// Day is the day of the purchase.
	Day ledger.Date

	// Market is the market the purchase happened in. It is empty when the
	// owner named none.
	Market string

	// Invoice is the invoice of the purchase. It is empty when the owner
	// named none.
	//
	// It is the WORD the owner said at the time of the purchase: the
	// number she read on the document she showed, or whatever she called
	// it. It is an utterance of the owner and it is kept verbatim.
	Invoice string

	// InvoiceID is the invoice the purchase came from. It is empty until
	// the invoice arrives: the purchase is written when the owner buys,
	// and the invoice comes later.
	//
	// It is the FACT of the link: the identity of the row of the invoice
	// the purchase points at.
	//
	// The word and the fact are TWO DIFFERENT FACTS, and the book never
	// compares them: the owner may read "FV-001" and the invoice the
	// purchase points at may carry another number. The word is what she
	// said, the fact is where the invoice is, and neither of them is
	// derived from the other.
	InvoiceID InvoiceID

	// Utterance is the sentence of the owner, verbatim. It is kept with
	// the purchase, so the entry can be audited and derived again.
	Utterance string

	// ConfirmedWith is the word the owner used to confirm the purchase.
	ConfirmedWith string

	// Lines are the lines of the purchase: what was bought, how much of
	// it, and what it cost.
	Lines []Line

	// Total is the money of the whole purchase, in whole pesos.
	Total ledger.Amount

	// CreatedAt is the moment the row was created. The storage filled it.
	CreatedAt time.Time
}

// Yes is the yes of the owner: the revision she saw and the word she used.
//
// The revision is what makes the confirmation exact: a draft that changed
// under her eyes is refused until it is shown again.
type Yes struct {
	// Revision is the revision of the draft the owner saw.
	Revision int

	// Word is the word she used to confirm it.
	Word string
}

// Confirmation is the outcome of the confirmation of a draft.
//
// It carries the purchase that was written and the three parts of the
// answer of Paca: what it recorded, what it did not understand and what it
// still needs.
type Confirmation struct {
	// Purchase is the purchase that was written.
	Purchase Purchase

	// Recorded is what the confirmation recorded: the lines of the
	// purchase.
	Recorded []Line

	// NotUnderstood is what Paca did not understand: the names the draft
	// was not sure about, with the options it offered.
	NotUnderstood []Ambiguity

	// StillNeeds is what the purchase still needs. It is empty when the
	// confirmation was accepted: a purchase without the money of its
	// lines is refused.
	StillNeeds []string

	// NewNames are the names the catalog of the business did not know: the
	// names that became ingredients of the business with this purchase.
	//
	// A name the catalog does not know is not an error: it is recorded as
	// the owner said it, and the answer tells her that it is new.
	NewNames []string
}

// Confirm turns a draft into the purchase it describes.
//
// The rules of the domain hold here:
//
//   - the word of the confirmation is required: it is kept with the record,
//     and a confirmation without it is refused;
//   - only a draft that waits is confirmed: a draft that is already
//     confirmed is never confirmed again;
//   - the revision the owner saw is the revision of the draft: a draft that
//     changed under her eyes is refused;
//   - a draft that expired is refused: the price of a market does not wait;
//   - the money of every line is required: the money is never inferred, and
//     a purchase without it moves no money.
//
// The day of the purchase is the day of the draft, the market and the
// invoice are the ones the owner named, and the sentence travels verbatim:
// the sentence keeps the exact wording of the owner, and the money of the
// book is whole pesos.
func Confirm(draft Draft, yes Yes, today ledger.Date) (Confirmation, error) {
	word := strings.TrimSpace(yes.Word)
	if word == "" {
		return Confirmation{}, fmt.Errorf("%w: the confirmation carries no word", ErrMissingConfirmation)
	}

	if draft.State != StateProposed {
		return Confirmation{}, fmt.Errorf("%w: the draft is in the state %q", ErrNotProposed, draft.State)
	}

	if yes.Revision != draft.Revision {
		return Confirmation{}, fmt.Errorf("%w: the owner saw the revision %d and the draft is at the revision %d",
			ErrStaleRevision, yes.Revision, draft.Revision)
	}

	if today.After(draft.ExpiresOn) {
		return Confirmation{}, fmt.Errorf("%w: the draft expired the day %v", ErrExpiredDraft, draft.ExpiresOn)
	}

	missing := missingOf(draft.Lines)
	if len(missing) > 0 {
		return Confirmation{}, fmt.Errorf("%w: the draft still needs %s", ErrStillNeeds, strings.Join(missing, ", "))
	}

	lines := linesOf(draft.Lines)
	total := ledger.Amount(0)
	for _, one := range lines {
		total += one.Price.Total
	}

	return Confirmation{
		Purchase: Purchase{
			DraftID:       draft.ID,
			BusinessID:    draft.BusinessID,
			Day:           draft.Day,
			Market:        draft.Market,
			Invoice:       draft.Invoice,
			Utterance:     draft.Utterance,
			ConfirmedWith: word,
			Lines:         lines,
			Total:         total,
		},
		Recorded:      lines,
		NotUnderstood: draft.Ambiguous,
		StillNeeds:    missingOf(draft.Lines),
	}, nil
}

// Movement answers the movement of the money of the purchase.
//
// The money of the payment comes from the account that pays and it lands in
// the account of the inventory of the business: the purchase is what the
// business bought, and the inventory is what it has.
//
// The description of the movement is the sentence of the owner: it is what
// the person reads in their book, in her own words.
func (p Purchase) Movement(paying, inventory account.ID) (ledger.Entry, error) {
	return ledger.NewEntry(p.BusinessID, inventory, paying, p.Total, p.Day, p.Utterance)
}

// linesOf turns the lines of a draft into the lines of a purchase.
//
// The money of a line is the money of the book: whole pesos. The money that
// was paid is kept, and the price of the unit is kept with it, so the line
// of the purchase says the same truth the line of the draft said.
func linesOf(lines []Line) []Line {
	written := make([]Line, 0, len(lines))

	for _, one := range lines {
		written = append(written, Line{
			Name:    one.Name,
			Measure: one.Measure,
			Price: Price{
				Total: one.Price.Amount(one.Measure.Quantity),
				Unit:  one.Price.Unit,
			},
			IngredientID: one.IngredientID,
		})
	}

	return written
}
